using UnityEditor;

namespace SolarMajesty.EditorTools
{
    /// <summary>
    /// Import settings for the application icons in Assets/Art/Icons.
    ///
    /// The PNGs are regenerated by Tools/release/icons/make_app_icons.py, so settings follow the
    /// folder instead of being clicked per file. The defaults would block-compress and mip the
    /// icons, which smears the 16 and 32 px sizes that were drawn pixel-for-pixel.
    /// </summary>
    public sealed class IconImportRules : AssetPostprocessor
    {
        private const string Root = "Assets/Art/Icons/";

        private void OnPreprocessTexture()
        {
            string path = assetPath.Replace('\\', '/');
            if (!path.StartsWith(Root)) return;

            var importer = (TextureImporter)assetImporter;
            importer.textureType = TextureImporterType.Default;
            importer.mipmapEnabled = false;
            importer.npotScale = TextureImporterNPOTScale.None;
            importer.textureCompression = TextureImporterCompression.Uncompressed;
            importer.alphaIsTransparency = true;
            importer.sRGBTexture = true;
            importer.isReadable = true;
            importer.wrapMode = UnityEngine.TextureWrapMode.Clamp;
            importer.filterMode = UnityEngine.FilterMode.Bilinear;
            importer.maxTextureSize = 1024;
        }
    }
}
